use xiom.io;

use xiom.string;
type Counter[T] = {
  items: Vec[T];
}

fn Counter.new[T]() -> Counter[T] {
  return Counter[T]{ items: Vec[T].new() };
}

fn Counter.add[T](&mut self, item: T) {
  self.items.push(item);
}

fn Counter.count[T](self) -> Int {
  return self.items.len();
}

fn main() -> Int {
  var str_counter: Counter[Str] = Counter[Str].new();
  str_counter.add("error");
  str_counter.add("warning");
  str_counter.add("info");
  io.println(to_string(str_counter.count()));

  var int_counter: Counter[Int] = Counter[Int].new();
  int_counter.add(10);
  int_counter.add(20);
  io.println(to_string(int_counter.count()));
  return 0;
}
